questionvariables.text:
stack_include("contribl://prooflib.mac");
proof_steps: [
  ["assume", "Assume, for contradiction, that \\(\\sqrt[3]{2}\\) is rational."],
  ["frac",   "Then \\(\\sqrt[3]{2} = \\dfrac{p}{q}\\), where \\(p\\) and \\(q\\) are integers, \\(q \\neq 0\\), and the fraction \\(\\dfrac{p}{q}\\) is in its simplest form."],
  ["cube",   "Cubing both sides, \\(2 = \\dfrac{p^3}{q^3}\\), so \\(p^3 = 2q^3\\)."],
  ["peven",  "So \\(p^3\\) is even. The cube of an odd number is odd, so \\(p\\) is even: \\(p = 2k\\) for some integer \\(k\\)."],
  ["qeven",  "Then \\(2q^3 = (2k)^3 = 8k^3\\), so \\(q^3 = 4k^3\\) is even, and so \\(q\\) is even."],
  ["contra", "So \\(p\\) and \\(q\\) are both even, and \\(\\dfrac{p}{q}\\) is not in its simplest form. This contradicts the choice of \\(p\\) and \\(q\\)."],
  ["conc",   "So the assumption is false, and \\(\\sqrt[3]{2}\\) is irrational."],
  ["d_irr",  "Assume, for contradiction, that \\(\\sqrt[3]{2}\\) is irrational."],
  ["d_sq",   "Squaring both sides, \\(2 = \\dfrac{p^2}{q^2}\\), so \\(p^2 = 2q^2\\)."]
];
proof_steps: random_permutation(proof_steps);
ta: proof("assume", "frac", "cube", "peven", "qeven", "contra", "conc");

feedbackvariables.text:
sa: parsons_decode(ans1);
sal: args(proof_flatten(sa));
[pd, saa]: proof_assessment(sa, proof_alternatives(ta));
has_sq: if member("d_sq", sal) then 1 else 0;
has_irr: if member("d_irr", sal) then 1 else 0;
